/**
 * Every node we can emit is checked against the schema.org vocabulary
 * (tests/fixtures/schemaorg-vocab.json, regenerated by
 * scripts/update-schema-vocab.mjs):
 *   - each @type is a schema.org class;
 *   - each property exists and is allowed on that type (domainIncludes,
 *     through superclasses);
 *   - each value fits the property's range: a nested node or an @id
 *     reference of a suitable type, an enumeration member of the right
 *     enumeration, or a string where the range admits text, URLs or dates.
 *
 * Run over a matrix of graphs: every entity mode, 0/1/2 bylines with roles,
 * every credential state, breadcrumbs, and the no-bylines fallback.
 */

import { describe, expect, it } from "vitest";

import { buildGraph, type Credit, type GraphInput, type SiteIdentity } from "../src/graph.js";
import vocab from "./fixtures/schemaorg-vocab.json";

type Node = Record<string, unknown>;
const V = vocab as {
	classes: Record<string, string[]>;
	properties: Record<string, { domains: string[]; ranges: string[] }>;
	members: Record<string, string>;
};

function ancestors(type: string): Set<string> {
	const out = new Set<string>([type]);
	const stack = [type];
	while (stack.length > 0) {
		for (const parent of V.classes[stack.pop()!] ?? []) {
			if (!out.has(parent)) {
				out.add(parent);
				stack.push(parent);
			}
		}
	}
	return out;
}

const TEXTUAL = new Set(["Text", "URL", "Date", "DateTime", "Time", "Number", "Integer", "Boolean"]);

/**
 * Deliberate departures from schema.org ranges, each backed by Google's
 * documentation. ListItem.item's range is Thing, but Google's BreadcrumbList
 * guide gives it as a plain URL string, which is the form its tests read.
 */
const STRING_ALLOWED = new Set(["ListItem.item"]);

function problems(graph: Node): string[] {
	const nodes = graph["@graph"] as Node[];
	const typeById = new Map(nodes.map((n) => [n["@id"] as string, n["@type"] as string]));
	const found: string[] = [];

	const fits = (value: unknown, ranges: string[], where: string): void => {
		if (typeof value === "string") {
			const member = value.startsWith("https://schema.org/") ? value.slice(19) : null;
			if (member && V.members[member]) {
				if (!ranges.some((r) => ancestors(V.members[member]!).has(r))) found.push(`${where}: ${member} is not in ${ranges}`);
				return;
			}
			if (!ranges.some((r) => TEXTUAL.has(r) || [...ancestors(r)].some((a) => TEXTUAL.has(a)))) {
				found.push(`${where}: a string, but the range is ${ranges.join("|")}`);
			}
			return;
		}
		if (Array.isArray(value)) return value.forEach((v, i) => fits(v, ranges, `${where}[${i}]`));
		if (value && typeof value === "object") {
			const o = value as Node;
			const type = (o["@type"] as string | undefined) ?? typeById.get(o["@id"] as string);
			if (!type) return void found.push(`${where}: reference to ${String(o["@id"])} which is not in the graph`);
			if (!ranges.some((r) => ancestors(type).has(r))) found.push(`${where}: ${type} is not a ${ranges.join("|")}`);
			if (o["@type"]) check(o, where);
		}
	};

	const check = (node: Node, where: string): void => {
		const type = node["@type"] as string;
		if (!V.classes[type]) return void found.push(`${where}: ${type} is not a schema.org class`);
		const lineage = ancestors(type);
		for (const [key, value] of Object.entries(node)) {
			if (key.startsWith("@")) continue;
			const prop = V.properties[key];
			if (!prop) {
				found.push(`${where}.${key}: not a schema.org property`);
				continue;
			}
			if (!prop.domains.some((d) => lineage.has(d))) found.push(`${where}.${key}: not allowed on ${type}`);
			if (typeof value === "string" && STRING_ALLOWED.has(`${type}.${key}`)) continue;
			fits(value, prop.ranges, `${where}.${key}`);
		}
	};

	nodes.forEach((n) => check(n, String(n["@type"])));
	return found;
}

// ── The matrix ───────────────────────────────────────────────────

const SITE = "https://example.com";
const today = "2026-09-30";
const credentials = [
	{ name: "Active", issuer: "Body", dateIssued: "2019-06-01", url: "https://example.com/v", badgeUrl: "https://example.com/b.png" },
	{ name: "Expiring", issuer: "Body", dateIssued: "2020-01-01", dateExpires: "2030-01-01" },
	{ name: "Pending", dateIssued: "2027-01-01" },
	{ name: "Expired", dateIssued: "2010-01-01", dateExpires: "2020-01-01" },
	{ name: "Hidden", published: false },
];
const site = (mode: SiteIdentity["mode"]): SiteIdentity => ({
	mode,
	person: {
		name: "Alex",
		jobTitle: "Physio",
		description: "Bio",
		url: "https://alex.example",
		image: "https://example.com/a.jpg",
		sameAs: ["https://linkedin.com/in/a"],
		knowsAbout: ["Physiotherapy"],
		credentials,
	},
	organization: {
		name: "Org AB",
		logo: "https://example.com/logo.png",
		description: "Clinic",
		sameAs: ["https://facebook.com/org"],
		knowsAbout: ["Rehab"],
		certifications: [{ ...credentials[0]!, certNumber: "N1" }, ...credentials.slice(1)],
	},
	worksFor: true,
	founder: true,
	ownerGroup: "owner",
});
const credit = (group: string, role: Credit["role"]): Credit => ({
	group,
	name: group,
	bio: "Bio",
	websiteUrl: "https://people.example/" + group,
	role,
	profile: { jobTitle: "Writer", image: "https://example.com/p.jpg", sameAs: ["https://x.example/p"], knowsAbout: ["Topic"], worksFor: true, credentials },
});
const page = (isArticle: boolean): GraphInput["page"] => ({
	url: `${SITE}/posts/a`,
	canonical: `${SITE}/posts/a`,
	siteUrl: SITE,
	siteName: "Site",
	isArticle,
	title: "A post",
	description: "About it",
	image: `${SITE}/img.jpg`,
	datePublished: "2026-09-01T10:00:00Z",
	dateModified: "2026-09-02T10:00:00Z",
	breadcrumbs: [
		{ name: "Home", url: "/" },
		{ name: "Posts", url: "/posts" },
	],
	fallbackAuthor: "Theme Author",
});

const cases: Array<[string, GraphInput]> = [];
for (const mode of ["person", "organization", "both"] as const) {
	for (const [label, credits] of [
		["no bylines", []],
		["one author", [credit("g1", "author")]],
		["author, editor, reviewer, contributor", [credit("g1", "author"), credit("g2", "editor"), credit("g3", "reviewer"), credit("g4", "contributor")]],
		["the owner byline", [credit("owner", "author")]],
		["bylines unavailable", undefined],
	] as const) {
		cases.push([`${mode}, ${label}`, { today, site: site(mode), credits: credits as Credit[] | undefined, page: page(true) }]);
	}
	cases.push([`${mode}, not an article`, { today, site: site(mode), credits: [], page: page(false) }]);
}

describe("every node fits the schema.org vocabulary", () => {
	it.each(cases)("%s", (_label, input) => {
		expect(problems(buildGraph(input))).toEqual([]);
	});

	it("the checker catches a property on the wrong type", () => {
		const bad = { "@graph": [{ "@type": "EducationalOccupationalCredential", "@id": "x", name: "X", validUntil: "2030-01-01" }] };
		expect(problems(bad)).toEqual(["EducationalOccupationalCredential.validUntil: not allowed on EducationalOccupationalCredential"]);
	});
});
